  RelicConfig_129304_BattleDesc = {
    Text = "<OrangeQuality:Золото гармония>:«Гармония арифметики»приводит к максимальному увеличению арифметики на 1 пункт, за каждую 1% усиления урона Эффект глубины исследования духа увеличивается на 1%.\n<OrangeQuality:Дар размерности>:В начале исследования случайно получить 1 'Изображение измерения', лимит руки увеличивается на 2.\n<OrangeQuality:Ритуал благословения>:Награда за победу над первым и вторым этапами лидера изменяется на случайный благословенный реликвия 3 из 1.\n<RedQuality:Долгосрочная усталость>:Эффект восстановления всех жизней в бою снижен на 50%, выбор 'Выцветшие останки' при 'погребении' изменяется на восстановление 25% максимальной жизни.\n<RedQuality:Симптом вертиго>:В начале боя текущее безумие и серебряная энергия всех пробуждённых снижается на 50%.\n<RedQuality:Коридор вечной ночи>:В начале исследования базовое безумие и лимит серебряной энергии всех пробуждённых увеличивается на 50%."
