  RelicConfig_13854_StoryDesc = {
    Text = "Добро пожаловать в волшебный цирк мисс Касии! Будьте осторожны, не трогайте магические атрибуты без необходимости. Если случайно получите Укус, это будет очень плохо. \nВ конце концов, последствия, когда он в последний раз попробовал вкус крови, были весьма ужасными. \n\nШляпа мигнула глазом, как будто вот-вот вырвется из кокона."
