  RelicConfig_140276_BattleDesc = {
    Text = "<OrangeQuality:Отчаяние>:В начале хода за каждый потерянный 1% макс. здоровья временный финальный Урон повышается на 5%. Если в прошлом ходу сработало Сопротивление смерти, Эффект удваивается.\n<RedQuality:Превосходство>:Макс. здоровье всех врагов повышается на 300%."
  },
  RelicConfig_140276_Desc = {
    Text = "<OrangeQuality:Отчаяние>:В начале хода за каждый потерянный 1% макс. здоровья временный финальный Урон повышается на 5%. Если в прошлом ходу сработало Сопротивление смерти, Эффект удваивается.\n<RedQuality:Превосходство>:Макс. здоровье всех врагов повышается на 300%."
  },
  RelicConfig_140276_Name = {
    Text = "<RedQuality:Маятник измерений — Бой насмерть>"
  },
  RelicConfig_140277_BattleDesc = {
    Text = "<OrangeQuality:Размножение>: каждый ход при первом использовании «Навыка» каждым пробуждённым создаются 2 временные исходные копии этого навыка. При использовании командной карты с затратами вычислительной мощности 0 или 1 все пробуждённые получают 5 ед. ярости.\n<RedQuality:Бастион>: при использовании карты с исходными затратами вычислительной мощности 3 и более все враги получают щит в размере 20% макс. здоровья."
  },
  RelicConfig_140277_Desc = {
    Text = "<OrangeQuality:Размножение>: каждый ход при первом использовании «Навыка» каждым пробуждённым создаются 2 временные исходные копии этого навыка. При использовании командной карты с затратами вычислительной мощности 0 или 1 все пробуждённые получают 5 ед. ярости.\n<RedQuality:Бастион>: при использовании карты с исходными затратами вычислительной мощности 3 и более все враги получают щит в размере 20% макс. здоровья."
  },
  RelicConfig_140277_Name = {
    Text = "<RedQuality:Маятник измерений – Тревога>"
  },
  RelicConfig_140278_BattleDesc = {
    Text = "<OrangeQuality:Возрождение>:Получаемые щит и эффекты восстановления повышаются на 25%. При восстановлении здоровья или получении щита за каждый 1% от макс. здоровья в виде восстановления или щита получите 10% временного усиления урона.\n<RedQuality:Шёпот>:Каждый ход получаете Эффект снижения силы, равный 10% от макс. здоровья."
  },
  RelicConfig_140278_Desc = {
    Text = "<OrangeQuality:Возрождение>:Получаемые щит и эффекты восстановления повышаются на 25%. При восстановлении здоровья или получении щита за каждый 1% от макс. здоровья в виде восстановления или щита получите 10% временного усиления урона.\n<RedQuality:Шёпот>:Каждый ход получаете Эффект снижения силы, равный 10% от макс. здоровья."
