    Text = "<RedQuality:Маятник измерений — Устрашение>"
  },
  RelicConfig_140279_BattleDesc = {
    Text = "<OrangeQuality:Рассвет>:Базовое безумие всех пробуждённых снижается на 30 ед. Финальный Урон первого за ход взрыва безумия повышается на 200%, восстановление щита и здоровья повышается на 100%. После каждых 5 использований взрыва безумия выберите 1 пробуждённого для пробуждения и обновите Эффект усиления взрыва безумия.\n<RedQuality:Истощение>:Базовая энергия серебряного ключа повышается на 200%"
  },
  RelicConfig_140279_Desc = {
    Text = "<OrangeQuality:Рассвет>:Базовое безумие всех пробуждённых снижается на 30 ед. Финальный Урон первого за ход взрыва безумия повышается на 200%, восстановление щита и здоровья повышается на 100%. После каждых 5 использований взрыва безумия выберите 1 пробуждённого для пробуждения и обновите Эффект усиления взрыва безумия.\n<RedQuality:Истощение>:Базовая энергия серебряного ключа повышается на 200%"
  },
  RelicConfig_140279_Name = {
    Text = "<RedQuality:Маятник измерений — Проклятие>"
  },
  RelicConfig_140280_BattleDesc = {
    Text = "<OrangeQuality:Очнувшись>: после первого за ход применения взрыва ярости перезарядка взрыва ярости этого пробуждённого сбрасывается, он получает 50 ед. ярости, и создаются временные копии всех его «Навыков» с затратами вычислительной мощности 0.\n<RedQuality:Печать>: после первого за ход применения взрыва ярости остальные пробуждённые запечатываются."
  },
  RelicConfig_140280_Desc = {
    Text = "<OrangeQuality:Очнувшись>: после первого за ход применения взрыва ярости перезарядка взрыва ярости этого пробуждённого сбрасывается, он получает 50 ед. ярости, и создаются временные копии всех его «Навыков» с затратами вычислительной мощности 0.\n<RedQuality:Печать>: после первого за ход применения взрыва ярости остальные пробуждённые запечатываются."
  },
  RelicConfig_140280_Name = {
    Text = "<RedQuality:Маятник измерений – Дуэль>"
  },
  RelicConfig_140281_BattleDesc = {
    Text = "<OrangeQuality:Эхо>:В начале хода вытяните 3 командные карты с наибольшей вычислительной мощностью из колоды вытягивания. Первая разыгранная за ход командная Карта срабатывает 2 раза.\n<RedQuality:Головокружение>:После розыгрыша командной карты сбросьте все остальные командные карты, чья стоимость вычислительной мощности не ниже её."
  },
  RelicConfig_140281_Desc = {
    Text = "<OrangeQuality:Эхо>:В начале хода вытяните 3 командные карты с наибольшей вычислительной мощностью из колоды вытягивания. Первая разыгранная за ход командная Карта срабатывает 2 раза.\n<RedQuality:Головокружение>:После розыгрыша командной карты сбросьте все остальные командные карты, чья стоимость вычислительной мощности не ниже её."
  },
  RelicConfig_140281_Name = {
    Text = "<RedQuality:Маятник измерений — Смятение>"
  },
  RelicConfig_140282_BattleDesc = {
    Text = "<OrangeQuality:Великая мощь>: Урон от <PowerIconKeywords:Силы> всех пробуждённых увеличен на 50%. За каждое нанесение урона пробуждённый получает [Arg2] ед. временной <PowerIconKeywords:Силы>.\n<RedQuality:Бесплотность>: в начале боя все враги получают 50 слоёв <ParcloseIconKeywords:Барьера>."
  },
  RelicConfig_140282_Desc = {
    Text = "<OrangeQuality:Великая мощь>: Урон от <PowerIconKeywords:Силы> всех пробуждённых увеличен на 50%. За каждое нанесение урона пробуждённый получает [Arg2] ед. временной <PowerIconKeywords:Силы>.\n<RedQuality:Бесплотность>: в начале боя все враги получают 50 слоёв <ParcloseIconKeywords:Барьера>."
