  },
  RelicConfig_140840_BattleDesc = {
    Text = "Лимит руки +1. В начале боя создаёт 1 карту «<DerivativeCardKeywords_148:驭魇>» и помещает её в руку. При разыгрывании «Базового удара» Пробуждённого расход арифметики «<DerivativeCardKeywords_148:驭魇>» -1, нанося всем врагам [Arg1] единиц Коррозии. При разыгрывании «Базовой защиты» Пробуждённого получает [Arg2] единицы Силы, итоговый урон и Сила следующего разыгрывания «<DerivativeCardKeywords_148:驭魇>» увеличиваются на [Arg3]%."
  },
  RelicConfig_140840_Desc = {
    Text = "Лимит руки +1. В начале боя создаёт 1 карту «<DerivativeCardKeywords_148:驭魇>» и помещает её в руку. При разыгрывании «Базового удара» Пробуждённого расход арифметики «<DerivativeCardKeywords_148:驭魇>» -1, нанося всем врагам [Arg1] единиц Коррозии. При разыгрывании «Базовой защиты» Пробуждённого получает [Arg2] единицы Силы, итоговый урон и Сила следующего разыгрывания «<DerivativeCardKeywords_148:驭魇>» увеличиваются на [Arg3]%."
  },
  RelicConfig_140840_Name = {
    Text = "Борьба обречённого"
  },
  RelicConfig_140840_StoryDesc = {
    Text = "Обречённый страшится перемен, страшится того, что события выйдут из-под контроля, а в самой глубине души он в Истерии боится потери.\n Он снова и снова дует в свисток, желая подчинить всё Свисту, но не может удержать ничего."
  },
  RelicConfig_143665_BattleDesc = {
    Text = "В начале хода Понт получает [Arg1] Алиемус. После подбора в начале следующего боя создаётся 3 постоянных «Раб-измождь». При разыгрывании «Раб-измождь» Понт получает 3 Алиемус."
  },
  RelicConfig_143665_Desc = {
    Text = "В начале хода Понт получает [Arg1] Алиемус. После подбора в начале следующего боя создаётся 3 постоянных «Раб-измождь». При разыгрывании «Раб-измождь» Понт получает 3 Алиемус."
  },
  RelicConfig_143665_Name = {
    Text = "<OrangeQuality:Изображение измерения · Понт>"
  },
  RelicConfig_145438_BattleDesc = {
    Text = "В начале хода Лотан: Китовластица получает [Arg1] единиц Алиемуса. «Клинок, разрывающий мир» в начале следующего хода освобождает Преследование «Клинок пустоты»: наносит всем врагам Урон в размере 400% АТК Лотан: Китовластицы. Этот Урон учитывает Усиление урона, полученное «Клинком, разрывающим мир» через «Двуручный меч: Китопад», и считается «ударом»."
  },
  RelicConfig_145438_Desc = {
    Text = "В начале хода Лотан: Китовластица получает [Arg1] единиц Алиемуса. «Клинок, разрывающий мир» в начале следующего хода освобождает Преследование «Клинок пустоты»: наносит всем врагам Урон в размере 400% АТК Лотан: Китовластицы. Этот Урон учитывает Усиление урона, полученное «Клинком, разрывающим мир» через «Двуручный меч: Китопад», и считается «ударом»."
  },
  RelicConfig_145438_Name = {
    Text = "<OrangeQuality:Изображение измерения·Лотан: Китовластица>"
  },
  RelicConfig_146128_BattleDesc = {
    Text = "Лимит руки +1. В начале боя или после того, как разыграть «<DerivativeCardKeywords_157:Кость меча>», поместить 1 карту «<DerivativeCardKeywords_155:Кость безумия>» в руку и Замешать 1 карту «<DerivativeCardKeywords_156:Кость ран>» в Стопку добора. Если в течение одного хода разыграть «<DerivativeCardKeywords_155:Кость безумия>» и «<DerivativeCardKeywords_156:Кость ран>» одновременно, объединить эти две карты в «<DerivativeCardKeywords_157:Кость меча>» и поместить её в руку."
  },
  RelicConfig_146128_Desc = {
    Text = "Лимит руки +1. В начале боя или после того, как разыграть «<DerivativeCardKeywords_157:Кость меча>», поместить 1 карту «<DerivativeCardKeywords_155:Кость безумия>» в руку и Замешать 1 карту «<DerivativeCardKeywords_156:Кость ран>» в Стопку добора. Если в течение одного хода разыграть «<DerivativeCardKeywords_155:Кость безумия>» и «<DerivativeCardKeywords_156:Кость ран>» одновременно, объединить эти две карты в «<DerivativeCardKeywords_157:Кость меча>» и поместить её в руку."
  },
  RelicConfig_146128_Name = {
    Text = "Латы из китовой кости"
