  RelicConfig_147547_BattleDesc = {
    Text = "В начале хода Касия получает [Arg1] безумия. При взятии каждой карты Касия получает [Arg2] единиц безумия. Когда Касия освобождает вспышку безумия, все враги теряют [Arg3] единиц силы."
  },
  RelicConfig_147547_Desc = {
    Text = "В начале хода Касия получает [Arg1] безумия. При взятии каждой карты Касия получает [Arg2] единиц безумия. Когда Касия освобождает вспышку безумия, все враги теряют [Arg3] единиц силы."
  },
  RelicConfig_147547_Name = {
    Text = "<OrangeQuality:размерность изображение·Касия>"
  },
  RelicConfig_147665_BattleDesc = {
    Text = "Лимит арифметики и количество вытягиваемых карт за ход +1. В начале хода <FaxianKeywords:Обнаружение> 3 «<Caroboo_Tips:Королевского шоколада Мэри>» на выбор. Только 1 из них настоящий: выбрав настоящий, получите его положительный Эффект и рассейте 1 случайное отрицательное Состояние; выбрав ложный, получите его отрицательный Эффект, а при следующем <FaxianKeywords:Обнаружении> количество настоящих вариантов +1 и Эффекты удваиваются — сбрасывается после выбора настоящего."
  },
  RelicConfig_147665_Desc = {
    Text = "Лимит арифметики и количество вытягиваемых карт за ход +1. В начале хода <FaxianKeywords:Обнаружение> 3 «<Caroboo_Tips:Королевского шоколада Мэри>» на выбор. Только 1 из них настоящий: выбрав настоящий, получите его положительный Эффект и рассейте 1 случайное отрицательное Состояние; выбрав ложный, получите его отрицательный Эффект, а при следующем <FaxianKeywords:Обнаружении> количество настоящих вариантов +1 и Эффекты удваиваются — сбрасывается после выбора настоящего."
