  },
  RelicConfig_149665_BattleDesc = {
    Text = "Текущая среда считается «Ледяными просторами».\nГиперборея: после фазы вытягивания карт накладывает 1 слой <SlowIconKeywords:Замедления> и <RetainIconKeywords:Удержания> на 2 незамороженные Командные карты с наибольшей Арифметикой в руке. Когда любая Командная карта имеет не менее 3 слоёв <SlowIconKeywords:Замедления>, снимает с неё <SlowIconKeywords:Замедление> и наложенное в этом бою <RetainIconKeywords:Удержание>, «замораживает» её и накладывает 25 слоёв <TempPowerKeywords2:Усиления>."
  },
  RelicConfig_149665_Desc = {
    Text = "Текущая среда считается «Ледяными просторами».\nГиперборея: после фазы вытягивания карт накладывает 1 слой <SlowIconKeywords:Замедления> и <RetainIconKeywords:Удержания> на 2 незамороженные Командные карты с наибольшей Арифметикой в руке. Когда любая Командная карта имеет не менее 3 слоёв <SlowIconKeywords:Замедления>, снимает с неё <SlowIconKeywords:Замедление> и наложенное в этом бою <RetainIconKeywords:Удержание>, «замораживает» её и накладывает 25 слоёв <TempPowerKeywords2:Усиления>."
