  },
  RelicConfig_20166_BattleDesc = {
    Text = "<ProficientInRealmsIconKeywords:Мастерство границ> увеличивается на 100. Переместите первую сыгранную в каждом ходу карту обратно в руку. В начале ультра-хода, когда лимит карт в руке +5, скопируйте ваши карты в руке."
  },
  RelicConfig_20166_Desc = {
    Text = "<ProficientInRealmsIconKeywords:Мастерство царства> увеличивается на 100. Каждую первую карту, сыгранную в каждом ходу, возвращайте из сброса в руку. В начале ультра-хода, когда лимит рук +5, скопируйте ваши карты в руке, скопированные карты добавляют <NothingnessIconKeywords:Ускользание> и <DepleteIconKeywords:расход>."
