  RelicConfig_20168_BattleDesc = {
    Text = "Лимит щупалец +2. После освобождения Вознесения Урон шупалец +[Arg1]. Если в одном ходу было освобождено 3 раза Вознесение, то активируется каждое щупальце один раз."
