  RelicConfig_20169_BattleDesc = {
    Text = "<ProficientInRealmsIconKeywords:Мастерство границ> увеличивается на 100. За каждую разыгранную карту <EmbryoFusionIconKeywords:Слияние Зародыша> +10, если здоровье ниже 25%, увеличение составляет 20, максимальное количество активаций за ход — 10 раз."
