  RelicConfig_20172_BattleDesc = {
    Text = "При разыгрывании 3 карт команды за ход получите 1 карту <DerivativeCardKeywords_4:\"Озарение\">, при 6 картах получите ещё 1 карту <DerivativeCardKeywords_4:\"Озарение\">, а при 10 картах в начале следующего хода вы можете выбрать 2 карты из колоды и положить их в руку."
  },
  RelicConfig_20172_Desc = {
    Text = "Получите 1 карту <DerivativeCardKeywords_4:\"Озарение\">, когда количество разыгранных карт команды в каждом раунде достигнет 3. Получите ещё 1 карту <DerivativeCardKeywords_4:\"Озарение\">, когда количество достигнет 6. Когда количество достигнет 10, в начале следующего раунда вы можете выбрать 2 карты из колоды и положить их в руку."
