  RelicConfig_23689_BattleDesc = {
    Text = "После подбора все пробуждённые получают 30 очков алиемуса. Каждый раз, когда вы используете вспышку безумия, увеличивайте счётчик на 1. После освобождения воспоминания получите [Arg1] очков временной настороженности, [Arg2] очков временной <PowerIconKeywords:Огромная Огромная Огромная Огромная сила> и все пробуждённые получают 6 очков алиемуса, расходуя все счётчики, каждое очко счётчика дополнительно действует 1 раз."
  },
  RelicConfig_23689_Desc = {
    Text = "После поднятия все пробуждения получают 30 единиц безумия. Каждый раз при выпуске вспышки безумия увеличивается Счётчик на 1. После выпуска ключевой команды получить [Arg1] единиц временной защиты, [Arg2] единиц временной <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, все пробуждения получают 6 единиц безумия, расходуется весь Счётчик, каждая единица счетчика действует дополнительно 1 раз."
