  },
  RelicConfig_23690_BattleDesc = {
    Text = "За каждое дополнительно полученное 1 очко арифметики или каждую дополнительно вытянутую 1 карту Кража у всех врагов [Arg1] очков <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, получить 4% временный критический шанс, Эффект от элиты или босса удваивается. В начале ультра-хода получите [Arg2] очков <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, крит. Урон +15%."
  },
  RelicConfig_23690_Desc = {
    Text = "За каждую дополнительно полученную 1 единицу арифметики или каждую дополнительно вытянутую 1 карту Кража у всех врагов [Arg1] очков <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, получить 4% временного критического шанса, Эффект для элиты или битвы с боссом удваивается. В начале ультра-хода получите [Arg2] очков <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, крит. Урон +15%."
