  RelicConfig_55874_BattleDesc = {
    Text = "После боя получите [Arg1] слоев \"Перо и чернила\". Когда \"Перо и чернила\" достигнут 2 слоев, они будут потрачены, и одна Карта \"Образ\" случайно будет помещена в колоду."
