  RelicConfig_57667_BattleDesc = {
    Text = "Изначально имеете 2 уровня Божественной силы матриарха. После третьего хода в начале каждого хода вы можете выбрать: потратить Божественную силу матриарха для получения различных эффектов или восстановить Божественную силу матриарха. Если получите фатальный Урон, то возродитесь и потратите всю Божественную силу матриарха, восстановив 10% здоровья за каждый Уровень. Эффект может сработать только 1 раз."
  },
  RelicConfig_57667_Desc = {
    Text = "Изначально есть 2 уровня Божественной силы матриарха, после третьего хода в начале каждого хода можно выбрать: потратить Божественную силу матриарха для получения различных эффектов или восстановить Божественную силу матриарха. Если получен фатальный Урон, то произойдёт Возрождение и будет потрачена вся Власть Божественной Матери, каждый Уровень восстанавливает 10% здоровья, может сработать только 1 раз."
  },
