  RelicConfig_60723_BattleDesc = {
    Text = "Макс. арифметика увеличивается на 1, в начале хода дополнительно возьмите 1 карту, вы получите карту \"Симфония гармонии\". Если заразыграны 3 карты команды с одинаковым расходом арифметики, все пробуждённые получают 20 очков Алиемуса, количество сбросов сбрасывается в начале хода и после срабатывания."
