  },
  RelicConfig_65406_BattleDesc = {
    Text = "В начале хода получите [Arg1] карт<DerivativeCardKeywords_71:\"Сияние человечества\">.\n<D05EX_Relic:Все ваши усилия были не напрасны, вы почти спасли группу исследователей, и выжившие искренне благодарны вам.>"
  },
  RelicConfig_65406_Desc = {
    Text = "В начале хода получите [Arg1] карт<DerivativeCardKeywords_71:\"Сияние человечества\">.\n<D05EX_Relic:Ваши усилия были не напрасны, вы почти сохранили группу исследователей, выжившие искренне благодарны вам.>"
  },
  RelicConfig_65406_Name = {
    Text = "<OrangeQuality:спасательная медаль·платина>"
  },
  RelicConfig_65406_StoryDesc = {
    Text = "Все твои усилия были не напрасны, ты почти полностью сохранил команду научной экспедиции, выжившие искренне благодарят тебя."
  },
  RelicConfig_65407_BattleDesc = {
    Text = "В начале хода получите [Arg1] карт<DerivativeCardKeywords_72:\"Блеск человечества\">.\n<D05EX_Relic:Вы создали невероятное чудо, все люди выжили после катастрофы, вы великий герой в сердцах людей, и ваша легенда, возможно, скоро будет передаваться вокруг снежной горы.>"
  },
  RelicConfig_65407_Desc = {
    Text = "В начале хода получите [Arg1] карт<DerivativeCardKeywords_72:\"Блеск человечества\">.\n<D05EX_Relic:Вы создали невероятное чудо, все люди выжили после катастрофы, вы великий герой в сердцах людей, и ваша легенда, возможно, будет передаваться вокруг снежной горы.>"
  },
  RelicConfig_65407_Name = {
    Text = "<OrangeQuality:спасательная медаль · бриллиант>"
  },
  RelicConfig_65407_StoryDesc = {
    Text = "Вы совершили невероятное чудо, все люди выжили после катастрофы, вы великий герой в сердцах людей, и легенда о вас, возможно, будет передаваться среди снежных гор."
  },
  RelicConfig_65408_BattleDesc = {
    Text = "В начале хода получите [Arg1] карт<DerivativeCardKeywords_68:\"Проблеск человечества\">.\n<D05EX_Relic:Чтобы выбраться из снежной горы, вы выбрали стратегию приоритета выгоды и наблюдали, как люди умирают один за другим, а взгляд выживших на вас полон страха, а не благодарности.>"
  },
  RelicConfig_65408_Desc = {
    Text = "В начале хода получите [Arg1] карт<DerivativeCardKeywords_68:\"Проблеск человечества\">.\n<D05EX_Relic:Чтобы выбраться из снежной горы, вы выбрали стратегию приоритета выгоды и наблюдали, как люди один за другим умирают, а взгляды выживших полны больше страха, чем благодарности.>"
  },
  RelicConfig_65408_Name = {
    Text = "<OrangeQuality:медаль спасения Бронза>"
  },
  RelicConfig_65408_StoryDesc = {
    Text = "Чтобы выбраться из снежной горы, ты выбрал стратегию приоритета выгоды и наблюдал, как люди один за другим умирают, а в взглядах выживших на тебя Страх больше, чем благодарность."
  },
  RelicConfig_65409_BattleDesc = {
    Text = "В начале хода получите [Arg1] карт<DerivativeCardKeywords_69:\"Слабый Погоня за светом человечества\">.\n<D05EX_Relic:Вы, возможно, старались, хотя половина людей погибла, вы по крайней мере спасли другую половину, ведь жертвы всегда неизбежны.>"
  },
  RelicConfig_65409_Desc = {
    Text = "В начале хода получите [Arg1] карт<DerivativeCardKeywords_69:\"Слабый Погоня за светом человечества\">.\n<D05EX_Relic:Вы, возможно, старались, хотя половина людей погибла, вы по крайней мере спасли другую половину, ведь жертва всегда неизбежна.>"
  },
  RelicConfig_65409_Name = {
    Text = "<OrangeQuality:медаль спасения · серебро>"
  },
  RelicConfig_65409_StoryDesc = {
    Text = "Вы, возможно, приложили усилия. Хотя половина людей умерла, вы всё же спасли другую половину. В конце концов, жертва неизбежна."
  },
  RelicConfig_65410_BattleDesc = {
    Text = "В начале хода получите [Arg1] карт<DerivativeCardKeywords_70:\"Погоня за светом человечности\">.\n<D05EX_Relic:Ты спас многих людей, изменив их судьбы. Ты уже сделал всё возможное, разве нет?>"
  },
  RelicConfig_65410_Desc = {
    Text = "В начале хода получите [Arg1] карт<DerivativeCardKeywords_70:\"Погоня за светом человечности\">.\n<D05EX_Relic:Ты спас многих людей, изменив их судьбы. Ты уже сделал всё возможное, разве нет?>"
  },
  RelicConfig_65410_Name = {
    Text = "<OrangeQuality:медаль спасения · золото>"
  },
  RelicConfig_65410_StoryDesc = {
    Text = "Ты спас большую часть людей, изменил их трагическую судьбу, ты уже сделал всё что мог, Не?"
  },
  RelicConfig_65456_BattleDesc = {
    Text = "В начале боя перетасуйте 3 случайные карты \"симптомов\", получайте [Arg1] очков силы при разыгрывании \"симптомов\".\n<D05EX_Relic:С вашей помощью, никто из научной экспедиции не выжил, вы безразлично добились максимальной выгоды для себя, но действительно ли это того стоит?>"
  },
  RelicConfig_65456_Desc = {
    Text = "В начале боя перетасуйте 3 случайные \"симптомы\", при розыгрыше \"симптома\" получите [Arg1] очков силы.\n<D05EX_Relic:С вашей помощью, никто не выжил из научной экспедиции, вы безразлично добились максимальной выгоды для себя, но стоит ли это всего?>"
  },
