  RelicConfig_68651_BattleDesc = {
    Text = "При начале боя пробуждаются все пробуждённые тела, добавляется <DerivativeCardKeywords_84:«Сумерки: незаконченная восковая фигура»> в руку, копируются все карты из колоды для розыгрыша. Каждый ход дополнительно вытягивается 5 карт, получаете 5 очков арифметики. После розыгрыша «ударить» или «защита» получаете [Arg1] очков щита."
  },
  RelicConfig_68651_Desc = {
    Text = "При начале боя пробуждаются все пробуждённые тела, добавляется <DerivativeCardKeywords_84:«Сумерки: незаконченная восковая фигура»> в руку, копируются все карты из колоды для розыгрыша. Каждый ход дополнительно вытягивается 5 карт, получаете 5 очков арифметики. После розыгрыша «ударить» или «защита» получаете [Arg1] очков щита."
  },
  RelicConfig_68651_Name = {
    Text = "<OrangeQuality:\"серебряное ядро · Страх\">"
  },
  RelicConfig_68652_BattleDesc = {
    Text = "В начале боя пробуждайте всех пробуждённых, добавьте в руку <DerivativeCardKeywords_85:\"Сумерки: мутировавшее сердце\">. В начале хода вы можете сбросить любое количество карт из руки и взять такое же количество карт. В нечетные ходы получите [Arg1] очков временной силы и добавьте в руку <DerivativeCardKeywords_97:\"Неиссякаемая воля β\">. В четные ходы получите [Arg2] очков временной настороженности и добавьте в руку <DerivativeCardKeywords_98:\"Спрятатьсяβ\">."
  },
  RelicConfig_68652_Desc = {
    Text = "В начале боя пробудите всех пробуждённых, добавьте в руку карту <DerivativeCardKeywords_85:\"Сумерки: мутировавшее сердце\">. В начале хода можно выбрать любое количество карт в руке для сброса, чтобы взять равное количество карт. В нечетные ходы получите [Arg1] очков временной силы, добавьте в руку карту \"<DerivativeCardKeywords_97:Неиссякаемая воля β>\". В четные ходы получите [Arg2] очков временной настороженности, добавьте в руку <DerivativeCardKeywords_98:\"Спрятатьсяβ\">."
  },
  RelicConfig_68652_Name = {
    Text = "<OrangeQuality:\"Чистое серебряное ядро · Пронзающая кость\">"
  },
  RelicConfig_68653_BattleDesc = {
    Text = "В начале боя пробудите всех пробуждённых и положите в руку <DerivativeCardKeywords_83:\"Сумерки: наивный ответный дар\">. Все пробуждённые могут дополнительно использовать 1 раз вознесение за ход, после использования вознесения снизьте силу врага на [Arg2] очков. В начале хода все пробуждённые получают [Arg1] очков безумия."
  },
  RelicConfig_68653_Desc = {
    Text = "В начале боя пробуждайте всех пробуждённых и добавьте в руку <DerivativeCardKeywords_83:\"Сумерки: наивный ответный дар\">. Все пробуждённые могут дополнительно использовать 1 раз Вознесение за ход, после использования Вознесения снизьте силу врагов на [Arg2] очков. В начале хода все пробуждённые получают [Arg1] очков Алиемуса."
  },
  RelicConfig_68653_Name = {
    Text = "<OrangeQuality:\"Чистое серебряное ядро · Плачущее\">"
  },
  RelicConfig_68654_BattleDesc = {
    Text = "При начале битвы пробудите всех пробуждённых, добавьте в руку <DerivativeCardKeywords_88:\"Сумерки: Занавес опускается утопии\">, лимит руки команды +2, лимит хранения ключесвета +100%. После освобождения воспоминания временный критический шанс и крит. Урон всех пробуждённых + [Arg1]%, получите щит на 20% максимального здоровья, вытяните карты, пока лимит руки не будет достигнут."
  },
  RelicConfig_68654_Desc = {
    Text = "При начале битвы пробуждаются все пробуждённые, добавьте <DerivativeCardKeywords_88:\"Сумерки: Занавес опускается утопии\"> в руку, лимит руки команды +2, лимит хранения ключесвета +100%. После активации воспоминания все пробуждённые получают временный критический шанс и крит. Урон + [Arg1]%, получают щит на 20% максимального здоровья, вытяните карты, пока лимит руки не будет достигнут."
  },
  RelicConfig_68654_Name = {
    Text = "<OrangeQuality:\"Чистое Серебряное Ядро · Безумие\">"
  },
  RelicConfig_68655_BattleDesc = {
