  RelicConfig_72226_BattleDesc = {
    Text = "Лимит руки +1. В начале хода, если исследование не проводилось, выберите одно из незавершённых исследований, после завершения получите соответствующий результат исследования «Долл: Преисподняя». При завершении 3 исследований, поместите 1 карту «Конец иллюзий» в руку, эта реликвия утрачивает силу."
  },
  RelicConfig_72226_Desc = {
    Text = "Лимит руки +1. В начале хода, если исследование не проводилось, выберите одно исследование, которое ещё не проводилось, и завершите его. После завершения получите соответствующий результат исследования «Долл: Преисподняя». При завершении 3 исследований, поместите 1 карту «Конец иллюзий» в руку, эта реликвия теряет силу."
  },
  RelicConfig_72226_Name = {
    Text = "Конец научной рукописи"
  },
  RelicConfig_74832_BattleDesc = {
    Text = "Лимит руки +1. В начале хода получите одну настраиваемую \"Запрещённый обмен\", разыграв \"Запрещённый обмен\", можно снова активировать в следующем ходу. Разыгрывая различные типы \"Карт команды\", когда у вас есть \"Запрещённый обмен\", улучшайте соответствующие эффекты."
  },
  RelicConfig_74832_Desc = {
    Text = "Максимальное количество карт на руке +1. В начале хода получите одну настраиваемую \"Запрещённый обмен\", после розыгрыша \"Запрещённого Обмена\" можно будет снова активировать в следующем ходу. Разыгрывая разные типы \"Карты команды\", когда у вас есть \"Запрещённый обмен\", вы улучшите соответствующие эффекты."
  },
  RelicConfig_74832_Name = {
    Text = "Приглашение шейпшифтера"
  },
  RelicConfig_74832_StoryDesc = {
    Text = "Текст на письме постоянно изменяется, неизменно превращаясь в неотразимое желание."
  },
  RelicConfig_78664_BattleDesc = {
    Text = "После розыгрыша 4 карт команды, принадлежащих разным пробуждённым, в одном ходу, итоговый Урон, наносимый всеми пробуждёнными, увеличивается на [Arg1]%, и они теряют [Arg2] очков алиемуса. Эффект может срабатывать не более одного раза за ход."
  },
  RelicConfig_78664_Desc = {
    Text = "После разыгрывания 4 Карт команды, принадлежащих разным пробуждённым, в одном ходе, итоговый Урон всех пробуждённых увеличивается на [Arg1]%, и они теряют [Arg2] очков алиемуса, Эффект срабатывает максимум 1 раз за ход."
  },
  RelicConfig_78664_Name = {
    Text = "<RedQuality:странный Коготь>"
  },
  RelicConfig_78664_StoryDesc = {
    Text = "Трудноузнаваемый биологический вид."
  },
  RelicConfig_78665_BattleDesc = {
    Text = "В начале хода возьмите на [Arg1] карт меньше. Каждый раз, когда вы разыгрываете карту с фактическим расходом арифметики, равным или превышающим [Arg2], получайте 1 единицу арифметики, максимум [Arg3] раз за ход."
  },
  RelicConfig_78665_Desc = {
    Text = "В начале хода тяните на [Arg1] карт(ы). При разыгрывании 1 карты с расходом вычислительной мощности не менее [Arg2] получайте 1 единицу вычислительной мощности, максимум [Arg3] раз за ход."
  },
  RelicConfig_78665_Name = {
    Text = "<RedQuality:колокольчик с причитаниями>"
  },
  RelicConfig_78665_StoryDesc = {
    Text = "Динь линь, динь линь, ребёнок плачет;\nДинь линь, динь линь, ребёнок кричит.\nДинь линь, динь линь, ребёнок кричит от боли;\nДинь линь, динь линь, он голоден, ты знаешь."
  },
  RelicConfig_78666_BattleDesc = {
    Text = "В начале хода получить [Arg1] контратаку. После применения [Arg2] раз вспышки безумия за ход, удалить [Arg3]% постоянной контратаки, получить временную контратаку в размере [Arg4]% от удаленного количества, с перезарядкой в [Arg5] ходов."
  },
  RelicConfig_78666_Desc = {
    Text = "В начале хода получить [Arg1] единиц контратаки. После применения [Arg2] раз Взрыва безумия за ход, удалить у себя [Arg3]% постоянной контратаки, получить временную контратаку в размере [Arg4]% от удаляемого количества, перезарядка [Arg5] ходов."
  },
  RelicConfig_78666_Name = {
    Text = "<RedQuality:останки путника>"
  },
  RelicConfig_78666_StoryDesc = {
    Text = "Священная часть.\nДаже при разделении от тела, её следы распространились повсюду."
  },
  RelicConfig_78667_BattleDesc = {
    Text = "После фазы вытягивания карт дополнительно вытянуть [Arg1] карту и выбрать [Arg2] карты из руки для сброса."
  },
  RelicConfig_78667_Desc = {
    Text = "После фазы вытягивания карт дополнительно вытянуть [Arg1] карту и выбрать [Arg2] карты из руки для сброса."
  },
  RelicConfig_78667_Name = {
    Text = "<RedQuality:кепи мага хитрости>"
  },
  RelicConfig_78667_StoryDesc = {
    Text = "Добро пожаловать в волшебный цирк госпожи Касии! Будьте осторожны, не трогайте магические предметы без разрешения. Если вы случайно получите Укус, это будет ужасно. \nВедь в последний раз, когда оно tasted кровь, последствия были очень ужасными. \n\nШляпа подмигнула, словно вот-вот вырвется из кокона."
  },
  RelicConfig_78668_BattleDesc = {
    Text = "После использования Возвышения Ключесвета выберите [Arg1] Непроизводных карт команды соответствующего Пробуждённого и израсходуйте их, затем поместите [Arg2] дополнительно израсходованных Базовых копий в Стопку добора, Руку и Стопку сброса соответственно."
  },
  RelicConfig_78668_Desc = {
