  RelicConfig_78669_BattleDesc = {
    Text = "Получите [Arg1] силы в начале битвы. В начале хода за каждые [Arg2] единиц постоянной силы получите [Arg3] единиц временной силы, максимум [Arg4] единиц временной силы, и в конце хода потеряете половину щита, полученного от этой реликвии временной силы."
  },
  RelicConfig_78669_Desc = {
    Text = "Получите [Arg1] очков силы в начале битвы. В начале хода за каждые [Arg2] единиц постоянной силы получайте [Arg3] единиц временной силы, максимум [Arg4] единиц временной силы, и в конце хода потеряйте половину щита, полученного от временной силы этой реликвии."
