  RelicConfig_78670_BattleDesc = {
    Text = "Увеличение базового урона всех пробуждённых на [Arg1]%, при каждом сбросе колоды дополнительно увеличивается на [Arg2]%, но 1 Карта \"Потрясение\" помещается в руку, максимальное значение увеличения составляет [Arg3]%."
