  RelicConfig_78673_BattleDesc = {
    Text = "После возжигания ключесвета дополнительно расходуется [Arg1] очков ключесвета, что делает стоимость в арифметике полученной карты возжигания гносиса равной 0, а также даёт соответствующему пробуждённому дополнительно [Arg2] алиемус."
