  RelicConfig_78673_Desc = {
    Text = "После пробуждения серебряного ключа дополнительно расходуется [Arg1] очков ключесвета, что делает расход вычислительной мощности полученных карт пробуждения духа равным 0, а после розыгрыша соответствующий пробуждённый получает дополнительно [Arg2] очков алиемуса."
