  RelicConfig_78675_BattleDesc = {
    Text = "В начале хода, если у вас более [Arg1] постоянных щупальцев, вы теряете [Arg2] щупальцев и получаете [Arg3] временных щупальцев, иначе получаете [Arg4] постоянных щупальцев."
