  RelicConfig_78675_StoryDesc = {
    Text = "Наслаждаться страданием."
  },
  RelicConfig_79408_BattleDesc = {
    Text = "Лимит руки +2, количество вытягиваемых карт +2. \"Чистые Воспоминания\" начинается с 5 уровней, разыгрывание карты с меткой изменяет \"Чистые Воспоминания\". Когда \"Чистые Воспоминания\" ниже 5, за каждую единицу ниже окончательный Урон увеличивается на 10%, щит и восстановление здоровья уменьшаются на 5%; когда \"Чистые Воспоминания\" выше 5, за каждую единицу выше щит и восстановление здоровья увеличиваются на 5%, окончательный Урон уменьшается на 10%."
  },
  RelicConfig_79408_Desc = {
    Text = "Лимит руки +2, количество вытаскиваемых карт +2. \"Чистые Воспоминания\" начинается с 5 уровней, разыгрывание карт с меткой изменяет \"Чистые Воспоминания\". Когда \"Чистые Воспоминания\" ниже 5, за каждую единицу ниже итоговый Урон +10%, щит и восстановление жизни уменьшаются на 5%; когда \"Чистые Воспоминания\" выше 5, за каждую единицу выше щит и восстановление жизни увеличиваются на 5%, итоговый Урон -10%."
  },
  RelicConfig_79408_Name = {
    Text = "\"Память\" и \"Сон\""
  },
  RelicConfig_79408_StoryDesc = {
    Text = "«Приходи, послушай меня.»\n«Позволь мне сделать твою память и мечту.»\n«Преобразовать в невероятно вкусный десерт.»"
  },
  RelicConfig_80340_BattleDesc = {
    Text = "В начале хода Клементина получает [Arg1] алиемуса. Эффекты всех карт команды Клементины по урону, щиту, восстановлению жизни, получению алиемуса и получению ключесвета увеличиваются на 1."
