  RelicConfig_80340_Desc = {
    Text = "В начале хода Клементина получает [Arg1] алиемус. Эффекты всех карт команды Клементины по увеличению урона, щита, восстановления жизни, получения алиемуса и получения ключесвета увеличиваются на 1."
