  RelicConfig_83509_BattleDesc = {
    Text = "В начале исследования лимит объектов +1, Пробуждённым из 'Эквор' предоставляется 'Изображение измерения' их. За каждого 'Пробуждённого' из 'Эквор' в команде лимит объектов +1."
