  RelicConfig_83510_BattleDesc = {
    Text = "В начале исследования лимит объектов +1, Пробуждённым из 'Каро' предоставляется 'Измерение' их. За каждого 'Пробуждённого' из 'Каро' в команде лимит объектов +1."
