  },
  RelicConfig_83606_BattleDesc = {
    Text = "Лимит руки +1. В начале хода, если нет \"Выбор штурмана\", положите его в руки. \n Каждый раз, когда Босс теряет 10% от своего начального максимального здоровья, получайте 1 Уровень \"Поднять паруса\", максимум 10 уровней. \"Поднять паруса\" может увеличить Эффект \"Поднять паруса\". \n Каждый раз, когда вы теряете 10% от своего начального максимального здоровья, получайте 1 Уровень \"Анкеровать\", максимум 10 уровней. \"Анкеровать\" может увеличить Эффект \"Убежище\"."
  },
  RelicConfig_83606_Desc = {
    Text = "Лимит руки + 1. Если в начале хода не получить \"Выбор штурмана\", положите его в руки. \nКаждый раз, когда Босс теряет 10% от начального максимального здоровья, получает 1 Уровень \"Поднять паруса\", предел 10 уровней, \"Поднять паруса\" может увеличить Эффект \"Поднять Паруса\". \nКаждый раз, когда вы теряете 10% от начального максимального здоровья, получаете 1 Уровень \"Анкеровать\", предел 10 уровней, \"Анкеровать\" может увеличить Эффект \"Убежище\"."
  },
