  RelicConfig_84127_Desc = {
    Text = "В начале хода Корпосант получает [Arg1] алиемуса, получает 1 временное щупальце. Каждый раз, когда срабатывает Сопротивление смерти, Корпосант получает [Arg2] очков алиемуса, помещая 1 карту с ценой в арифметике 0 и добавленной ценой \"Карающие молнии\" в руку."
