  RelicConfig_84127_Name = {
    Text = "<OrangeQuality:Измерение изображения·Коперсант>"
  },
  RelicConfig_89252_BattleDesc = {
    Text = "Лимит арифметики увеличивается на 1, количество вытягиваемых карт за ход увеличивается на 1, в начале боя получаете [Arg1] уровней \"Клетки судьбы\".\nКаждый Уровень \"Клетки судьбы\" уменьшает производимый всеми пробуждёнными алиемус на [Arg2]%, при каждом использовании взрыва безумия Уровень \"Клетки судьбы\" уменьшается на 1. После удаления всех \"Клеток судьбы\" все пробуждённые получают [Arg3] очков алиемуса и получают \"Непоколебимое сердце\": производимый всеми пробуждёнными алиемус увеличивается на [Arg4]%, возможность использовать взрыв безумия 2 раза за ход."
  },
  RelicConfig_89252_Desc = {
    Text = "Лимит арифметики увеличивается на 1, количество вытягиваемых карт за ход увеличивается на 1, в начале боя получите [Arg1] уровней \"Клетки судьбы\".\nКаждый Уровень \"Клетки судьбы\" снижает генерируемый всеми пробуждёнными алиемус на [Arg2]%, и при каждом освобождении вспышки алиемуса уменьшается на 1 Уровень \"Клетки судьбы\". После удаления всех \"Клеток судьбы\" все пробуждённые получают [Arg3] очков алиемуса и получают \"Непоколебимое сердце\": генерируемый всеми пробуждёнными алиемус увеличивается на [Arg4]%, и за ход можно освободить вспышку алиемуса 2 раза."
  },
