  RelicConfig_89645_BattleDesc = {
    Text = "Лимит руки +2, после активации Возвышения временный итоговый Урон увеличивается на 10%.\nКогда Карта попадает в Ультра пространство, 1 \"Зародыш\" в руке преобразуется в \"Непорочное дитя\".\nКаждый раз, когда генерируется 1 \"Зародыш\", цена в арифметике одной случайной карты в сверхпространстве уменьшается на 1."
  },
  RelicConfig_89645_Desc = {
    Text = "Лимит руки +2, после активации Возвышения временный итоговый Урон увеличивается на 10%.\nПосле того как Карта попадает в Ультра пространство, 1 \"Зародыш\" в руке преобразуется в \"Непорочное дитя\".\nКаждый раз, когда создается 1 \"Зародыш\", цена в арифметике одной случайной карты из сверхпространства уменьшается на 1."
