  RelicConfig_89646_BattleDesc = {
    Text = "В начале хода получите 250 очков ключесвета.\nПосле пробуждения серебряного ключа положите 1 карту <DerivativeCardKeywords_129:\"Серебрянный Ключ Блеск\"> в руку.\nВ начале каждого хода обнаружьте 1 поддержку пробуждённого."
  },
  RelicConfig_89646_Desc = {
    Text = "В начале хода получите 250 очков ключесвета.\nПосле пробуждения серебряного ключа положите 1 карту <DerivativeCardKeywords_129:\"Серебрянный Ключ Блеск\"> в руку.\nВ начале каждого хода обнаружьте 1 поддержку пробуждённого."
