  RelicConfig_89647_BattleDesc = {
    Text = "Каждая первая Командная Карта за ход действует дополнительно 1 раз. \n При аннигиляции создается 1 щупальце. \n После переключения щупальца на стойку \"Девятый вал\" Эффект скачка следующей карты команды в этом ходу обязательно активируется, и 2 базовые копии помещаются в Ультра пространство, перезарядка 3 хода."
  },
  RelicConfig_89647_Desc = {
    Text = "Каждая первая Командная Карта в ходе действует дополнительно 1 раз. \nПри аннигиляции создается 1 щупальце. \nПосле переключения щупальца в стойку \"Девятый вал\" Эффект скачка следующей Карты команды в этом ходу обязательно срабатывает, и ее 2 базовые копии помещаются в Ультра пространство, перезарядка 3 хода."
  },
  RelicConfig_89647_Name = {
    Text = "Препарат «Суперструнный бездна морская»"
