  RelicConfig_89648_BattleDesc = {
    Text = "Мастерство царства увеличивается на 200 очков.\nПри расходе Багрового очага увеличивает Урон шупалец на 15%.\nКаждый раз при атаке щупальцем накапливается [Arg3] очков Багрового очага."
