  RelicConfig_91096_BattleDesc = {
    Text = "В начале хода обе стороны получают Уровень <Kuangre:безумие>, каждый Уровень <Kuangre:безумие> наносит активный и щупальцевый Урон с дополнительным 10% от урона равного <BleedingIconKeywords:Кровотечение>. \n За каждый 20% урона, нанесённого лидеру, все пробуждённые получают 10 Алиемуса. \n В начале боя <DerivativeCardKeywords_108:\"Вдохновление Потомства\"> и <DerivativeCardKeywords_109:\"Тело Потомства\"> перемешиваются в колоду для розыгрыша."
  },
  RelicConfig_91096_Desc = {
