    Text = "Лимит карт в руке +1. В начале боя получите «<DerivativeCardKeywords_116:Палитру>».\nВ начале хода получите 1 «<PrimaryColor:Цвет>», и 2 случайные карты приказов получают «<ColorInkKeywords:Когнитивный диссонанс>». После разыгрывания карты с «<ColorInkKeywords:Когнитивным диссонансом>» вы последовательно получаете 1 «<PrimaryColor:Цвет>».\n«<PrimaryColor:Цвет>» после разыгрывания записывается на «<DerivativeCardKeywords_116:Палитру>». Если на «<DerivativeCardKeywords_116:Палитре>» присутствуют 2 разных «<PrimaryColor:Основных цвета>», это даёт постоянный Эффект усиления.\nЕсли на палитре присутствуют 3 разных «<PrimaryColor:Основных цвета>», все враги немедленно теряют 5% макс. здоровья, и «<DerivativeCardKeywords_116:Палитра>» очищается."
  },
